<?php
require_once dirname(__DIR__).'/includes/bootstrap.php';require_module('approvals');if($_SERVER['REQUEST_METHOD']!=='POST')redirect('approvals/index.php');verify_csrf();$id=(int)($_POST['approval_id']??0);$action=strtolower($_POST['action']??'');$remarks=trim($_POST['remarks']??'');if(!in_array($action,['approve','reject'],true)){flash('danger','Invalid approval action.');redirect('approvals/index.php');}
$s=db()->prepare("SELECT a.*,COALESCE(b.department_id,e.department_id) department_id,COALESCE(b.budget_code,e.expense_code) request_code FROM approvals a LEFT JOIN budgets b ON a.request_type='budget' AND b.id=a.request_id LEFT JOIN expenses e ON a.request_type='expense' AND e.id=a.request_id WHERE a.id=? FOR UPDATE");db()->beginTransaction();try{$s->execute([$id]);$a=$s->fetch();if(!$a||$a['status']!=='Pending')throw new RuntimeException('This request is no longer pending.');$authorized=false;if($a['current_stage']==='department_manager'){$authorized=is_admin()||(has_role(['Sales Manager','Marketing Manager'])&&(int)$a['department_id']===(int)current_user()['department_id']);}elseif($a['current_stage']==='finance'){$authorized=is_admin()||has_role('Finance Manager');}if(!$authorized)throw new RuntimeException('You are not authorized for the current approval stage.');
if($action==='reject'){if($remarks==='')throw new RuntimeException('Remarks are required when rejecting a request.');db()->prepare("UPDATE approvals SET status='Rejected',remarks=?,updated_at=NOW() WHERE id=?")->execute([$remarks,$id]);$table=$a['request_type']==='budget'?'budgets':'expenses';$statusCol=$a['request_type']==='budget'?'approval_status':'status';db()->prepare("UPDATE $table SET $statusCol='Rejected',updated_at=NOW() WHERE id=?")->execute([$a['request_id']]);db()->prepare("INSERT INTO approval_history(approval_id,stage,action,action_by,remarks) VALUES(?,?, 'Rejected',?,?)")->execute([$id,$a['current_stage'],current_user()['id'],$remarks]);}
else{if($a['current_stage']==='department_manager'){db()->prepare("UPDATE approvals SET current_stage='finance',remarks=?,updated_at=NOW() WHERE id=?")->execute([$remarks,$id]);db()->prepare("INSERT INTO approval_history(approval_id,stage,action,action_by,remarks) VALUES(?,'department_manager','Approved',?,?)")->execute([$id,current_user()['id'],$remarks?:'Department manager approved']);}else{db()->prepare("UPDATE approvals SET status='Approved',remarks=?,updated_at=NOW() WHERE id=?")->execute([$remarks,$id]);$table=$a['request_type']==='budget'?'budgets':'expenses';$statusCol=$a['request_type']==='budget'?'approval_status':'status';db()->prepare("UPDATE $table SET $statusCol='Approved',updated_at=NOW() WHERE id=?")->execute([$a['request_id']]);db()->prepare("INSERT INTO approval_history(approval_id,stage,action,action_by,remarks) VALUES(?,'finance','Approved',?,?)")->execute([$id,current_user()['id'],$remarks?:'Finance approved']);}}
db()->commit();log_activity(strtoupper($action),'Approvals',ucfirst($action).' '.$a['request_code']);flash('success','Request '.($action==='approve'?'approved':'rejected').' successfully.');}catch(Throwable $e){db()->rollBack();flash('danger',$e->getMessage());}redirect('approvals/index.php');
